from lib import *
S = SS('x43')
steps = [
    step("什么都不配(Boot 默认的 /error)。IllegalStateException → 500 JSON {status:500, error:Internal Server Error, path};ResponseStatusException 418 → 418;带 @ResponseStatus(CONFLICT) 的异常 → 409;自定义业务异常 BizException → 500(业务码、信息都没有带出来);缺必需参数 → 400;不存在的路径 → 404;Filter 里抛异常 → 500 同样的 JSON。控制器内部的 @ExceptionHandler 管的 IllegalArgumentException → 422 文本。默认的 JSON 只有状态码、错误名和路径,没有异常信息。", t=tl(S(1)), mark=lidx(S(1), 'GET /e/biz', 'GET /e/illegal  [头 X-Boom]'), done=lidx(S(1), 'GET /e/illegal →', 'GET /e/rse', 'GET /e/annotated', 'GET /e/param', 'GET /nope'), b=bars([['自定义业务异常的状态码', 500, '500(信息丢失)'], ['ResponseStatusException(418)的状态码', 418, '418'], ['@ResponseStatus(CONFLICT)的状态码', 409, '409'], ['Filter 里抛异常的状态码', 500, '500']], 500, mark=[0, 3], done=[1, 2]), kv=KV([['默认 /error JSON', '只有 status、error、path'], ['业务异常', '500,信息不带出'], ['@ResponseStatus', '用注解里的状态码'], ['Filter 异常', '同样进 /error']], ['业务异常'])),
    step("spring.mvc.problemdetails.enabled=true。标准的 MVC 异常和 ResponseStatusException 变成 application/problem+json:ResponseStatusException 418 → {detail: 我是茶壶, status: 418, title: I'm a teapot};缺必需参数 → {detail: Required parameter 'q' is not present., status: 400, title: Bad Request};404 → {detail: No static resource nope., status: 404}。IllegalStateException、@ResponseStatus 的异常、自定义业务异常、Filter 里的异常仍然走默认的 /error JSON(application/json)。开关只管 Spring MVC 自己的标准异常。", t=tl(S(2)), mark=lidx(S(2), 'GET /e/illegal →', 'GET /e/biz', 'GET /e/annotated'), done=lidx(S(2), 'GET /e/rse', 'GET /e/param', 'GET /nope'), b=bars([['变成 problem+json 的路径个数', 3, '3:rse、param、nope'], ['仍是默认 JSON 的路径个数', 4, '4:illegal、annotated、biz、Filter']], 4, done=[0], mark=[1]), kv=KV([['标准 MVC 异常与 ResponseStatusException', 'problem+json'], ['自己的异常', '仍然默认 JSON'], ['开关', 'spring.mvc.problemdetails.enabled'], ['body', 'type、title、status、detail、instance']], ['开关'])),
    step("加上两个 @RestControllerAdvice(Adv 的 @Order(2) 继承 ResponseEntityExceptionHandler,里面有 IllegalStateException、IllegalArgumentException、RuntimeException 兜底、BizException 的处理器;Adv2 的 @Order(1) 只处理 IllegalStateException)。/e/illegal:Order(1) 的 Adv2 抢先处理。/e/biz:ProblemDetail → 422 application/problem+json {detail: 业务异常:余额不足, status: 422, title: 业务错误, type, code: 1001},自定义字段 code 在 JSON 里。/e/annotated(@ResponseStatus 的 ConflictEx):变成 500 [RuntimeException 兜底] ConflictEx: null——Advice 里的 RuntimeException 处理器比 @ResponseStatus 的解析更早生效,409 没了。/e/arg:仍是控制器内部的 422 处理器赢。Filter 里的异常:不经过 Advice,仍是默认 JSON。", t=tl(S(3)), mark=lidx(S(3), 'GET /e/annotated', 'GET /e/illegal  [头 X-Boom]'), done=lidx(S(3), 'GET /e/illegal →', 'GET /e/biz', 'GET /e/arg'), b=bars([['/e/biz 的状态码(ProblemDetail)', 422, '422'], ['/e/annotated 的状态码(被兜底吞掉)', 500, '500(原本是 409)'], ['Order(1) 的 Advice 抢先处理 /e/illegal', 1, '是'], ['控制器内 @ExceptionHandler 优先于 Advice', 1, '是']], 500, done=[0, 2, 3], mark=[1]), kv=KV([['@Order 小的 Advice', '先处理'], ['控制器内的 @ExceptionHandler', '优先于所有 Advice'], ['RuntimeException 兜底', '会吞掉 @ResponseStatus 异常的 409'], ['ProblemDetail', '可带自定义字段']], ['RuntimeException 兜底'])),
    step("处理器自己抛异常、控制器内处理器与 Advice 的优先级。UnsupportedOperationException 被 Advice 里的 RuntimeException 兜底处理器接住,这个处理器自己又抛 IllegalStateException:最终是 500 默认 JSON,处理器里抛出的异常不会再被 Advice 处理第二遍。/e/local 同时有控制器内部和 Advice 里的 IllegalArgumentException 处理器:422 控制器内部的赢。", t=tl(S(4)), mark=lidx(S(4), 'GET /e/inhandler'), done=lidx(S(4), 'GET /e/local'), b=bars([['处理器内抛异常之后的状态码', 500, '500(默认 JSON)'], ['控制器内处理器 vs Advice:状态码', 422, '422(控制器内的赢)']], 500, mark=[0], done=[1]), kv=KV([['处理器里再抛异常', '不再被 Advice 处理,落到默认 /error'], ['优先级', '控制器内 > Advice(@Order 小者先)'], ['异常类型', '更具体的类型先被匹配'], ['兜底', '兜底处理器要小心不要吞掉特殊异常']], ['处理器里再抛异常'])),
]
